import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { CinemaScene } from './scene';
import { ArchiveDirector } from './director';

let scene: CinemaScene | null = null;
let director: ArchiveDirector | null = null;
let root: HTMLElement | null = null;
let cleanup: Array<() => void> = [];

const eraNames = ['1986', '2003', '今天'] as const;

function createPage(container: HTMLElement): HTMLElement {
  const page = document.createElement('main');
  page.className = 'archive-page';
  page.innerHTML = `
    <header class="archive-masthead" aria-label="城市放映档案">
      <a class="archive-mark" href="#opening" aria-label="回到开场">城市放映档案 <span>示意记录 069</span></a>
      <p>同一街角 · 三段时间</p>
    </header>
    <section class="archive-opening" id="opening" aria-labelledby="archive-title">
      <div class="opening-copy">
        <p class="eyebrow">一座虚构社区影院的艺术化档案演绎</p>
        <h1 id="archive-title">最后亮着的<br>老招牌</h1>
        <p class="dek">当电影院从街区里慢慢退场，招牌、门廊和一张张票根，仍替同一个地点保存着光。</p>
        <a class="text-link" href="#evidence">沿同一街角查看年代 <span aria-hidden="true">↓</span></a>
      </div>
      <aside class="sign-note" aria-label="当前档案状态">
        <span class="pulse" aria-hidden="true"></span>
        <strong>今日仍亮</strong>
        <small>最后一块旧招牌</small>
      </aside>
    </section>
    <section class="archive-evidence" id="evidence" aria-labelledby="evidence-title">
      <div class="evidence-intro">
        <p class="eyebrow">同址比对</p>
        <h2 id="evidence-title">时间没有换一座建筑，<br>只反复覆盖它。</h2>
        <p>选择年代。立面色彩、票根痕迹和放映声的文字记录会在同一机位对齐显影。</p>
      </div>
      <div class="era-panel" aria-live="polite">
        <nav class="era-nav" aria-label="选择查看年代">
          <button type="button" data-era="0">1986</button>
          <button type="button" data-era="1">2003</button>
          <button type="button" data-era="2" aria-current="true">今天</button>
        </nav>
        <div class="evidence-readout">
          <p class="place-code">示意地点 / 街角 069</p>
          <p class="era-large" data-era-label>今天</p>
          <dl>
            <div><dt>立面</dt><dd data-facade>浅色外墙，门廊仍在</dd></div>
            <div><dt>票根</dt><dd data-ticket>仅存私人收藏扫描记录</dd></div>
            <div><dt>放映声</dt><dd data-sound>“机器停了，招牌每晚仍亮。”</dd></div>
          </dl>
        </div>
      </div>
      <p class="disclosure">边界说明：画面为同一虚构社区影院的艺术化连续演绎，并非特定城市、影院或公共设施的真实历史证据。</p>
    </section>
    <section class="archive-resolution" id="save" aria-labelledby="save-title">
      <div class="resolution-copy">
        <p class="eyebrow">让街角继续被看见</p>
        <h2 id="save-title">保存一段<br>城市放映记忆</h2>
        <p>留下一句你记得的散场时刻。它不会替代史料，但能成为下一次寻找的线索。</p>
        <button class="save-action" type="button">保存一段城市放映记忆</button>
        <p class="save-status" role="status" aria-live="polite"></p>
      </div>
      <div class="final-caption" aria-hidden="true">
        <span>街角 069</span><span>同址留存</span><span>今天</span>
      </div>
    </section>`;
  container.appendChild(page);
  return page;
}

startExperience(defineExperience({
  mount(context) {
    root = createPage(context.container);
    scene = new CinemaScene(context.canvas, context.viewport, context.quality);
    director = new ArchiveDirector(scene, context.reducedMotion);

    const buttons = Array.from(root.querySelectorAll<HTMLButtonElement>('[data-era]'));
    const label = root.querySelector<HTMLElement>('[data-era-label]');
    const facade = root.querySelector<HTMLElement>('[data-facade]');
    const ticket = root.querySelector<HTMLElement>('[data-ticket]');
    const sound = root.querySelector<HTMLElement>('[data-sound]');
    const save = root.querySelector<HTMLButtonElement>('.save-action');
    const status = root.querySelector<HTMLElement>('.save-status');
    const records = [
      ['1986', '米黄色瓷砖，手绘片名牌', '晚场票 · 0.35 元 · 纸边磨损', '“开场铃响，木门一起合上。”'],
      ['2003', '雨棚翻新，售票窗缩小', '录像厅联票 · 日期章褪色', '“胶片换盘声混进街边车流。”'],
      ['今天', '浅色外墙，门廊仍在', '仅存私人收藏扫描记录', '“机器停了，招牌每晚仍亮。”']
    ] as const;

    const selectEra = (index: number): void => {
      director?.selectEra(index);
      buttons.forEach((button, buttonIndex) => {
        if (buttonIndex === index) button.setAttribute('aria-current', 'true');
        else button.removeAttribute('aria-current');
      });
      const record = records[index];
      if (label) label.textContent = record[0];
      if (facade) facade.textContent = record[1];
      if (ticket) ticket.textContent = record[2];
      if (sound) sound.textContent = record[3];
    };

    buttons.forEach((button) => {
      const handler = (): void => selectEra(Number(button.dataset.era));
      button.addEventListener('click', handler);
      cleanup.push(() => button.removeEventListener('click', handler));
    });

    const saveHandler = (): void => {
      if (status) status.textContent = `${eraNames[director?.getSelectedEra() ?? 2]}年的街角记忆已在本次浏览中保存。`;
      save?.classList.add('is-saved');
      scene?.setSaved(true);
    };
    save?.addEventListener('click', saveHandler);
    cleanup.push(() => save?.removeEventListener('click', saveHandler));
  },
  update(frame) {
    director?.update(frame.progress, frame.pointer.x, frame.pointer.y, frame.elapsed, frame.delta);
    scene?.render();
  },
  resize(viewport) {
    scene?.resize(viewport);
  },
  dispose() {
    cleanup.forEach((release) => release());
    cleanup = [];
    director?.dispose();
    scene?.dispose();
    root?.remove();
    director = null;
    scene = null;
    root = null;
  }
}));

import * as THREE from 'three';

export interface ViewportLike {
  width: number;
  height: number;
  dpr: number;
}

export type SceneState = {
  era: number;
  archiveMix: number;
  resolve: number;
  inspectionX: number;
  inspectionY: number;
  elapsed: number;
};

const vertexShader = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position, 1.0);
  }
`;

const fragmentShader = `
  precision highp float;
  varying vec2 vUv;
  uniform sampler2D uArchive;
  uniform float uHasTexture;
  uniform float uAspect;
  uniform float uViewAspect;
  uniform float uEra;
  uniform float uArchiveMix;
  uniform float uResolve;
  uniform vec2 uInspect;
  uniform float uTime;
  uniform float uSaved;

  vec2 coverUv(vec2 uv) {
    vec2 scale = vec2(1.0);
    if (uViewAspect > uAspect) scale.y = uAspect / uViewAspect;
    else scale.x = uViewAspect / uAspect;
    return (uv - 0.5) * scale + 0.5;
  }

  vec3 fallbackStreet(vec2 uv) {
    vec3 paper = vec3(0.91, 0.88, 0.79);
    float road = smoothstep(0.56, 0.58, uv.y);
    float building = step(0.24, uv.y) * (1.0 - step(0.72, uv.y));
    vec3 color = mix(paper, vec3(0.70, 0.67, 0.58), road);
    color = mix(color, vec3(0.79, 0.72, 0.58), building * 0.62);
    float signShape = step(0.29, uv.x) * (1.0 - step(0.66, uv.x)) * step(0.38, uv.y) * (1.0 - step(0.46, uv.y));
    color = mix(color, vec3(0.67, 0.22, 0.12), signShape);
    return color;
  }

  vec3 eraSample(vec2 uv, float eraIndex) {
    float panel = clamp(eraIndex, 0.0, 2.0);
    vec2 atlasUv = vec2((uv.x + panel) / 3.0, uv.y);
    return texture2D(uArchive, atlasUv).rgb;
  }

  void main() {
    vec2 uv = coverUv(vUv);
    float eraFloor = floor(uEra);
    float eraBlend = smoothstep(0.0, 1.0, fract(uEra));
    vec3 a = eraSample(uv, eraFloor);
    vec3 b = eraSample(uv, min(2.0, eraFloor + 1.0));
    vec3 image = mix(a, b, eraBlend);
    image = mix(fallbackStreet(uv), image, uHasTexture);

    float archiveBand = smoothstep(0.18, 0.34, uArchiveMix) * (1.0 - smoothstep(0.78, 0.94, uArchiveMix));
    float ticketA = step(abs(vUv.x - 0.18), 0.10) * step(abs(vUv.y - 0.73), 0.045);
    float ticketB = step(abs(vUv.x - 0.77), 0.12) * step(abs(vUv.y - 0.30), 0.038);
    float perforation = 0.55 + 0.45 * step(0.45, fract(vUv.x * 72.0));
    vec3 ticketInk = vec3(0.73, 0.30, 0.17);
    image = mix(image, ticketInk, (ticketA + ticketB) * archiveBand * 0.32 * perforation);

    float inspection = 1.0 - smoothstep(0.06, 0.31, distance(vUv, uInspect));
    image *= 0.92 + inspection * 0.08 * archiveBand;
    float daylight = 0.10 + 0.08 * vUv.y;
    image += vec3(0.96, 0.80, 0.55) * daylight;
    image = mix(image, image * vec3(1.03, 0.98, 0.90), uResolve);
    image += vec3(0.72, 0.25, 0.10) * uSaved * 0.035;

    float edge = smoothstep(0.0, 0.16, vUv.x) * smoothstep(0.0, 0.16, 1.0 - vUv.x);
    edge *= smoothstep(0.0, 0.12, vUv.y) * smoothstep(0.0, 0.12, 1.0 - vUv.y);
    vec3 paper = vec3(0.95, 0.92, 0.84);
    image = mix(paper, image, 0.78 + edge * 0.22);
    gl_FragColor = vec4(image, 1.0);
  }
`;

export class CinemaScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.Camera();
  private readonly geometry = new THREE.PlaneGeometry(2, 2);
  private readonly material: THREE.ShaderMaterial;
  private readonly textureLoader = new THREE.TextureLoader();
  private texture: THREE.Texture | null = null;
  private disposed = false;
  private eraCurrent = 2;
  private savedCurrent = 0;

  constructor(canvas: HTMLCanvasElement, viewport: ViewportLike, quality: string) {
    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: quality !== 'low', powerPreference: quality === 'low' ? 'low-power' : 'high-performance' });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.setClearColor(0xf1eadb, 1);
    this.material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      depthTest: false,
      depthWrite: false,
      uniforms: {
        uArchive: { value: new THREE.Texture() },
        uHasTexture: { value: 0 },
        uAspect: { value: 1.5 },
        uViewAspect: { value: 1 },
        uEra: { value: 2 },
        uArchiveMix: { value: 0 },
        uResolve: { value: 0 },
        uInspect: { value: new THREE.Vector2(0.72, 0.45) },
        uTime: { value: 0 },
        uSaved: { value: 0 }
      }
    });
    this.scene.add(new THREE.Mesh(this.geometry, this.material));
    this.resize(viewport);
    this.textureLoader.setCrossOrigin('anonymous');
    this.textureLoader.load(
      '/creative-assets/cinema-memory-street-continuity-v1.png',
      (texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        this.texture = texture;
        this.material.uniforms.uArchive.value = texture;
        const image = texture.image as { width?: number; height?: number };
        const width = image.width ?? 3;
        const height = image.height ?? 2;
        this.material.uniforms.uAspect.value = (width / 3) / height;
        this.material.uniforms.uHasTexture.value = 1;
      },
      undefined,
      () => {
        if (!this.disposed) this.material.uniforms.uHasTexture.value = 0;
      }
    );
  }

  applyState(state: SceneState, delta: number, reducedMotion: boolean): void {
    const response = reducedMotion ? 1 : 1 - Math.exp(-Math.min(delta, 0.05) * 8);
    this.eraCurrent = THREE.MathUtils.lerp(this.eraCurrent, state.era, response);
    this.material.uniforms.uEra.value = this.eraCurrent;
    this.material.uniforms.uArchiveMix.value = state.archiveMix;
    this.material.uniforms.uResolve.value = state.resolve;
    this.material.uniforms.uInspect.value.set(state.inspectionX, state.inspectionY);
    this.material.uniforms.uTime.value = state.elapsed;
    this.savedCurrent = THREE.MathUtils.lerp(this.savedCurrent, this.material.uniforms.uSaved.value, response);
  }

  setSaved(saved: boolean): void {
    this.material.uniforms.uSaved.value = saved ? 1 : 0;
  }

  resize(viewport: ViewportLike): void {
    const dpr = Math.min(viewport.dpr, 2);
    this.renderer.setPixelRatio(dpr);
    this.renderer.setSize(viewport.width, viewport.height, false);
    this.material.uniforms.uViewAspect.value = viewport.width / Math.max(1, viewport.height);
  }

  render(): void {
    this.renderer.render(this.scene, this.camera);
  }

  dispose(): void {
    this.disposed = true;
    this.texture?.dispose();
    this.geometry.dispose();
    this.material.dispose();
    this.renderer.dispose();
  }
}

import { CinemaScene, SceneState } from './scene';

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

function smoothstep(edge0: number, edge1: number, value: number): number {
  const x = clamp01((value - edge0) / (edge1 - edge0));
  return x * x * (3 - 2 * x);
}

export class ArchiveDirector {
  private selectedEra = 2;
  private readonly scene: CinemaScene;
  private readonly reducedMotion: boolean;

  constructor(scene: CinemaScene, reducedMotion: boolean) {
    this.scene = scene;
    this.reducedMotion = reducedMotion;
  }

  selectEra(index: number): void {
    this.selectedEra = Math.min(2, Math.max(0, Math.round(index)));
  }

  getSelectedEra(): number {
    return this.selectedEra;
  }

  update(progress: number, pointerX: number, pointerY: number, elapsed: number, delta: number): void {
    const p = clamp01(progress);
    const evidenceArrival = smoothstep(0.24, 0.58, p);
    const resolution = smoothstep(0.78, 0.96, p);

    // 开场保持今日街景；中段由访客选择年代；结尾回到今日，使旧痕迹与仍亮的招牌共处。
    let era = 2;
    if (p > 0.25 && p < 0.84) era = this.selectedEra;

    // 指针只移动检查光域，并在档案比对段生效，不驱动主体追逐。
    const inspectX = p > 0.24 && p < 0.84 ? 0.5 + pointerX * 0.18 : 0.72;
    const inspectY = p > 0.24 && p < 0.84 ? 0.5 - pointerY * 0.12 : 0.45;

    const state: SceneState = {
      era,
      archiveMix: evidenceArrival * (1 - resolution * 0.72),
      resolve: resolution,
      inspectionX: inspectX,
      inspectionY: inspectY,
      elapsed: this.reducedMotion ? 0 : elapsed
    };
    this.scene.applyState(state, delta, this.reducedMotion);
  }

  dispose(): void {
    // Director owns no external resources.
  }
}

* { box-sizing: border-box; }
html { margin: 0; scroll-behavior: smooth; background: #f1eadb; }
body { margin: 0; max-width: 100%; overflow-x: clip; background: #f1eadb; color: #29332e; font-family: Inter, "Noto Sans SC", "PingFang SC", system-ui, sans-serif; }
button, a { font: inherit; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; z-index: 0; }
.archive-page { position: relative; z-index: 1; width: 100%; min-height: 310vh; overflow-x: clip; }
.archive-page::after { content: ""; position: fixed; inset: 0; pointer-events: none; z-index: -1; background: linear-gradient(90deg, rgba(241,234,219,.92) 0%, rgba(241,234,219,.62) 34%, transparent 61%), linear-gradient(0deg, rgba(241,234,219,.45), transparent 38%); }
.archive-masthead { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: flex-start; padding: 22px clamp(20px, 4vw, 64px); border-bottom: 1px solid rgba(41,51,46,.24); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; }
.archive-mark { color: inherit; text-decoration: none; font-weight: 720; }
.archive-mark span { display: block; margin-top: 5px; color: #6f7169; font-size: 9px; font-weight: 520; }
.archive-masthead > p { margin: 0; color: #5f665f; }
.archive-opening, .archive-evidence, .archive-resolution { position: relative; min-height: 100vh; padding: clamp(92px, 12vh, 138px) clamp(20px, 4vw, 64px) clamp(48px, 8vh, 90px); }
.archive-opening { display: grid; grid-template-columns: minmax(280px, 580px) 1fr; align-items: end; }
.opening-copy { align-self: center; max-width: 560px; }
.eyebrow { margin: 0 0 18px; color: #8f3f27; font-size: 11px; font-weight: 760; letter-spacing: .14em; text-transform: uppercase; }
h1, h2, p { max-width: 100%; }
h1 { margin: 0; max-width: 9em; font-family: "Noto Serif SC", "Songti SC", serif; font-size: clamp(44px, 6.6vw, 92px); font-weight: 520; line-height: .98; letter-spacing: -.06em; }
.dek { max-width: 430px; margin: 28px 0 22px; font-size: clamp(15px, 1.35vw, 18px); line-height: 1.75; }
.text-link { display: inline-flex; gap: 22px; align-items: center; min-height: 44px; color: #29332e; font-size: 13px; font-weight: 700; text-decoration: none; border-bottom: 1px solid currentColor; }
.sign-note { justify-self: end; align-self: center; width: 176px; padding: 16px 0; border-top: 1px solid rgba(41,51,46,.45); border-bottom: 1px solid rgba(41,51,46,.45); }
.sign-note strong, .sign-note small { display: block; margin-left: 22px; }
.sign-note small { margin-top: 5px; color: #646861; }
.pulse { float: left; width: 9px; height: 9px; margin-top: 5px; border-radius: 50%; background: #b3482d; box-shadow: 0 0 0 5px rgba(179,72,45,.12); }
.archive-evidence { min-height: 118vh; display: grid; grid-template-columns: minmax(260px, .75fr) minmax(420px, 1.25fr); gap: clamp(38px, 8vw, 130px); align-content: center; background: linear-gradient(90deg, rgba(241,234,219,.94) 0 38%, rgba(241,234,219,.36) 66%, rgba(241,234,219,.08)); }
.evidence-intro { max-width: 430px; }
.evidence-intro h2, .resolution-copy h2 { margin: 0; font-family: "Noto Serif SC", "Songti SC", serif; font-size: clamp(34px, 4.4vw, 68px); font-weight: 520; line-height: 1.08; letter-spacing: -.045em; }
.evidence-intro > p:last-child, .resolution-copy > p { max-width: 420px; margin: 24px 0 0; line-height: 1.75; color: #505850; }
.era-panel { align-self: center; padding: clamp(22px, 3vw, 42px); background: rgba(246,241,229,.88); border: 1px solid rgba(41,51,46,.22); backdrop-filter: blur(8px); }
.era-nav { display: flex; gap: 8px; padding-bottom: 22px; border-bottom: 1px solid rgba(41,51,46,.22); }
.era-nav button { min-width: 72px; min-height: 44px; padding: 8px 15px; border: 1px solid rgba(41,51,46,.28); border-radius: 99px; color: #29332e; background: transparent; cursor: pointer; }
.era-nav button[aria-current="true"] { color: #fff9ed; border-color: #a9482e; background: #a9482e; }
.era-nav button:focus-visible, .save-action:focus-visible, .text-link:focus-visible { outline: 3px solid #c77948; outline-offset: 3px; }
.place-code { margin: 24px 0 0; color: #72756d; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.era-large { margin: 6px 0 20px; color: #a9482e; font-family: Georgia, serif; font-size: clamp(46px, 7vw, 86px); line-height: 1; }
dl { margin: 0; }
dl div { display: grid; grid-template-columns: 76px 1fr; gap: 12px; padding: 12px 0; border-top: 1px solid rgba(41,51,46,.16); }
dt { color: #79786f; font-size: 12px; }
dd { margin: 0; font-size: 14px; line-height: 1.55; }
.disclosure { position: absolute; left: clamp(20px, 4vw, 64px); bottom: 30px; max-width: 760px; margin: 0; color: #686b65; font-size: 11px; line-height: 1.6; }
.archive-resolution { display: grid; grid-template-columns: minmax(280px, 560px) 1fr; align-items: center; background: linear-gradient(90deg, rgba(241,234,219,.94) 0%, rgba(241,234,219,.68) 38%, transparent 70%); }
.resolution-copy { max-width: 560px; }
.save-action { margin-top: 30px; min-height: 52px; padding: 14px 21px; border: 1px solid #923d28; border-radius: 2px; color: #fff8e9; background: #9e422b; font-weight: 750; cursor: pointer; }
.save-action:hover, .save-action.is-saved { background: #29332e; border-color: #29332e; }
.save-status { min-height: 1.6em; margin: 12px 0 0 !important; font-size: 12px; }
.final-caption { align-self: end; display: flex; justify-content: flex-end; gap: 22px; color: #323a35; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
@media (max-width: 760px) {
  .archive-page { min-height: 340vh; }
  .archive-page::after { background: linear-gradient(0deg, rgba(241,234,219,.9) 0%, rgba(241,234,219,.58) 56%, rgba(241,234,219,.12)); }
  .archive-masthead { padding: 17px 20px; }
  .archive-masthead > p { display: none; }
  .archive-opening, .archive-evidence, .archive-resolution { min-height: 108vh; padding: 92px 20px 44px; }
  .archive-opening { display: flex; flex-direction: column; justify-content: space-between; align-items: stretch; }
  .opening-copy { margin-top: auto; margin-bottom: 9vh; }
  h1 { max-width: 8em; font-size: clamp(43px, 13.5vw, 60px); line-height: 1.01; }
  .dek { margin-top: 20px; font-size: 15px; }
  .sign-note { justify-self: auto; align-self: flex-end; width: 154px; }
  .archive-evidence { display: flex; flex-direction: column; justify-content: center; gap: 30px; background: rgba(241,234,219,.72); }
  .evidence-intro h2, .resolution-copy h2 { font-size: clamp(34px, 10vw, 48px); }
  .era-panel { width: 100%; padding: 20px 16px; }
  .era-nav { gap: 6px; }
